import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

public class SecureCode {
    public static void main(String[] args) throws SQLException {
        // Establish connection securely
        String url = "jdbc:mysql://localhost:3306/mydatabase";
        String user = "username";
        String password = "password";

        try (Connection conn = DriverManager.getConnection(url, user, password)) {
            // Use PreparedStatement for secure execution of queries
            String sql = "SELECT * FROM users WHERE username = ?";
            PreparedStatement pstmt = conn.prepareStatement(sql);

            // Set parameters safely
            pstmt.setString(1, "admin");

            // Execute the prepared statement
            ResultSet rs = pstmt.executeQuery();

            while (rs.next()) {
                System.out.println(rs.getString("name"));
            }

            // Close resources
            rs.close();
            pstmt.close();
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}
```

In the bad code snippet, we directly execute a SQL query without properly escaping or sanitizing the input data (`'admin'`). This makes it vulnerable to SQL injection attacks if the input comes from untrusted sources.

The good code snippet demonstrates proper usage of `PreparedStatement`, which helps prevent SQL injection by ensuring that all inputs are treated as parameters rather than part of the SQL command itself. This way, any malicious input will be handled separately, making the application more secure against such attacks.

